// Workflow inventado: nombre -> {needs, minutos}. Cada job corre en su propio runner.
const jobs = {
  lint:    { needs: [],                 min: 1 },
  pruebas: { needs: [],                 min: 4 },
  build:   { needs: ['lint', 'pruebas'], min: 6 },
  e2e:     { needs: ['build'],           min: 5 },
  deploy:  { needs: ['build', 'e2e'],    min: 2 },
};
const fin = {};
function termina(n) {
  if (fin[n] !== undefined) return fin[n];
  const j = jobs[n];
  const empieza = Math.max(0, ...j.needs.map(termina));
  console.log(`${n.padEnd(8)} empieza en min ${empieza}, termina en min ${empieza + j.min}`);
  return (fin[n] = empieza + j.min);
}
const total = Math.max(...Object.keys(jobs).map(termina));
const facturado = Object.values(jobs).reduce((a, j) => a + j.min, 0);
console.log(`\nReloj de pared: ${total} min`);
console.log(`Minutos de runner facturables: ${facturado} min`);
console.log(`Costo de una corrida a 0,006 USD/min: ${(facturado * 0.006).toFixed(3)} USD`);
console.log(`Corridas por mes con 12 USD incluidos: ${Math.floor(12 / (facturado * 0.006))}`);
